import test, { after } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { mkdtemp, readFile, readdir, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { inflateRawSync } from 'node:zlib';

// Run from the site directory; FLOWCHARTCP_SITE can select another checkout.
const here = path.dirname(fileURLToPath(import.meta.url));
const site = path.resolve(process.env.FLOWCHARTCP_SITE ??
  (path.basename(here) === 'tests' ? path.join(here, '..') : process.cwd()));
const { compileLocalModules } = await import(pathToFileURL(path.join(site, 'scripts/local-modules.mjs')).href);
const { isCorpusSolutionReviewed } = await import(pathToFileURL(path.join(site, 'scripts/lib/corpus-progress.mjs')).href);
const json = async relative => JSON.parse(await readFile(path.join(site, relative), 'utf8'));
const digest = value => createHash('sha256').update(JSON.stringify(value)).digest('hex');
const id = 'word-boundary-comma-closure', domain = 'strings';
const prefix = ['changes', 'comma-propagation'];
const graphId = 'word-boundary-comma-conditions';
const guards = ['word-side-rules', 'sentence-boundaries', 'bounds'];
const complete = [...prefix, 'yes', 'yes', 'yes'];
const statement = 'https://icpc.global/worldfinals/problems/2018-ICPC-World-Finals/icpc2018.pdf#page=3';
const sketch = 'https://icpc.global/worldfinals/problems/2018-ICPC-World-Finals/finals2018solutions.pdf#page=2';
const matching = row => String(row.source).toLowerCase() === 'icpc' && row.problemId === 'wf2018_b';
const techniques = value => value.current.techniques ?? [];
const xml = value => value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

// Independently frozen from before-mushrooms flows/walks and before-comma audit.
// The embedded shapes select every original field/answer/label, permitting only
// additional choices, nodes and graphs. No /tmp baseline dependency remains.
const hashes = {
  "records": "548fed4d6a193d2cc21d8074be465d7864a20982c8c66db0c636082a1ef4edbc",
  "outcomes": "a48140da1fd2af3c982338a40ebcf2e8ef03dda41443aaf68f97be2e9e57dd23",
  "steps": "a3597b14655abd768619d23a3119d5ca8ebf96cbeb79f29e8eaa5e593048be6e",
  "nodes": "57985619d8c23ce4988bd1f46b5cd529d708c831fc9b6a2d37df774d4b1dd850",
  "terminals": "869019c000d9b840fcaa9ac981a91094a2d8feecee20a68994bfe298775284bb",
  "graphHeaders": "6db25283495c7eebf847afd3736d5ed2c0925397d4d55e32b2b0133426b69250",
  "auditRecord": "ae21addf0e09a42984737670112e9127f5f74c83f554154f426a60644f2c7035",
  "baselineFlowsBytes": "51b48b37676eb0d9d19a5306bd736b83950c8573ff4790bddb6853b4e7b0ea2e",
  "baselineWalksBytes": "5b8ed5210b22e1bbfc669c52f3e0cccda6910893a295345c2a7114aeab167724",
  "baselineAuditBytes": "f9b140ffae49cc34c138088d510802d99616cbdb5603c8efea7129ee9b57be08"
};
const frozen = JSON.parse(inflateRawSync(Buffer.from('', 'base64')).toString('utf8'));

let temporary;
const implementation = (async () => {
  temporary = await mkdtemp(path.join(tmpdir(), 'flowchartcp-comma-flow-'));
  await compileLocalModules(site, temporary);
  return {
    flow: await import(pathToFileURL(path.join(temporary, 'flow.js')).href),
    viewer: await import(pathToFileURL(path.join(temporary, 'diagram-viewer.js')).href),
  };
})();
after(async () => { await implementation; await rm(temporary, { recursive: true, force: true }); });
async function collection(expression) {
  return (await Promise.all((await readdir(path.join(site, 'data'))).filter(name => expression.test(name))
    .map(name => json('data/' + name)))).flat();
}
function walk(flow, choices, entry = domain) {
  const value = flow.walkFromRoot(choices, entry);
  assert.equal(value.consumed, choices.length, 'every answer is consumed');
  return value;
}
function enter(flow, state) {
  for (let count = 0; flow.evaluateState(state).current.type === 'route'; ++count) {
    assert(count < 100); state = flow.enterFlowRoute(state);
  }
  return state;
}
function replay(flow, choices) {
  let state = flow.initialState(domain);
  for (const choice of choices) state = flow.answerState(enter(flow, state), choice);
  return enter(flow, state);
}
const weight = state => state.answers.length + (state.trail ?? [])
  .reduce((sum, context) => sum + context.answers.length + 1, 0);
function checkSvg(flow, graph) {
  const svg = flow.renderFlowSvg(graph); let edges = 0;
  for (const node of graph.nodes) {
    assert(svg.includes(`data-node="${node.id}"`));
    if (node.type === 'question') for (const option of flow.getNodeOptions(node)) {
      ++edges;
      assert(svg.includes(`data-edge="${node.id}:${option.id}:${node.answers[option.id]}"`));
      assert(svg.includes(`<title>${xml(option.label)}</title>`), 'complete edge labels are accessible');
    }
    if (node.type === 'result') for (const technique of node.techniques ?? [])
      assert(svg.includes(`/flowchartcp/techniques/${technique}/`));
  }
  assert.equal((svg.match(/class="flow-edge /g) ?? []).length, edges);
  return svg;
}
function rawWalk(graphs, record) {
  const byId = new Map(graphs.map(graph => [graph.id, graph]));
  let graph = byId.get(record.entryGraphId ?? 'ranges'); assert(graph);
  let node = graph.nodes.find(node => node.id === graph.root), consumed = 0;
  const steps = [];
  for (let limit = 0; limit < 2000; ++limit) {
    assert(node);
    if (node.type === 'route') {
      graph = byId.get(node.graph); assert(graph);
      node = graph.nodes.find(node => node.id === graph.root); continue;
    }
    if (node.type !== 'question' || consumed === record.choices.length) {
      assert.equal(consumed, record.choices.length);
      return { graph: graph.id, node: node.id, type: node.type, techniques: node.techniques ?? [], steps };
    }
    const answer = record.choices[consumed++];
    assert(Object.hasOwn(node.answers, answer));
    const target = node.answers[answer]; steps.push({ graph: graph.id, node: node.id, answer, target });
    node = graph.nodes.find(node => node.id === target);
  }
  assert.fail('raw replay must terminate');
}
function projectNodes(graphs, shapes) {
  const byId = new Map(graphs.map(graph => [graph.id, new Map(graph.nodes.map(node => [node.id, node]))]));
  return shapes.map(([graphId, nodeId, fields, answers, options]) => {
    const node = byId.get(graphId)?.get(nodeId); assert(node, `${graphId}/${nodeId} remains`);
    return [graphId, nodeId, fields.map(field => node[field]),
      answers === null ? null : answers.map(answer => [answer, node.answers?.[answer]]),
      options === null ? null : options.map(option => {
        const found = node.options?.find(row => row.id === option); assert(found); return found;
      })];
  });
}

test('Comma feature entrance reaches exactly three model and size guards', async () => {
  const { flow } = await implementation;
  assert.deepEqual(flow.validateGraphs(), []); assert.equal(flow.entryGraphs.length, 15);
  const category = walk(flow, ['changes']);
  const option = flow.getNodeOptions(category.current).find(option => option.id === prefix[1]);
  assert(option); assert.doesNotMatch(option.label, /ICPC|Comma Sprinkler|wf2018_b|BFS/i);
  for (let at = 0; at < guards.length; ++at) {
    const value = walk(flow, [...prefix, ...Array(at).fill('yes')]);
    assert.equal(value.graph.id, graphId); assert.notEqual(value.graph.entry, true);
    assert.equal(value.current.type, 'question'); assert.equal(value.current.id, guards[at]);
    assert.deepEqual(flow.getNodeOptions(value.current).map(option => option.id).sort(), ['no', 'unknown', 'yes']);
    assert(!techniques(value).includes(id));
  }
  const result = walk(flow, complete);
  assert.equal(result.current.type, 'result'); assert.deepEqual(techniques(result), [id]);
  const text = JSON.stringify(result.graph);
  for (const term of [/前/, /後/, /同じ語/, /読点/, /文頭/, /文末/, /句点/, /空白/, /英小文字/, /100万|1,?000,?000|10\^6/]) assert.match(text, term);
});

test('every no and unknown guard answer enters condition-check', async () => {
  const { flow } = await implementation;
  for (let at = 0; at < guards.length; ++at) for (const answer of ['no', 'unknown']) {
    const value = walk(flow, [...prefix, ...Array(at).fill('yes'), answer]);
    assert.equal(value.graph.id, 'condition-check', `${guards[at]}/${answer}`);
    assert.equal(value.current.type, 'question'); assert(!techniques(value).includes(id));
  }
});

test('question and SVG views retain all labels, paths and the reusable article href', async () => {
  const { flow } = await implementation;
  const graph = flow.getGraph(graphId), svg = checkSvg(flow, graph), html = flow.renderFlowHtml('/flowchartcp/');
  assert(svg.includes(`/flowchartcp/techniques/${id}/`));
  assert(html.includes('data-view="questions"')); assert(html.includes('data-view="diagram"'));
  assert(html.includes(`data-graph-panel="${graphId}"`));
  for (const node of graph.nodes) {
    assert(html.includes(`id="flow-text-${graphId}-${node.id}"`)); assert(html.includes(xml(node.title)));
    if (node.type === 'question') for (const option of flow.getNodeOptions(node)) {
      assert(html.includes(xml(option.label))); assert(html.includes(`#flow-text-${graphId}-${node.answers[option.id]}`));
    }
  }
  assert(html.includes(`/flowchartcp/techniques/${id}/`));
});

test('all successful and rejected histories survive sharing, highlighting, diagrams and Back', async () => {
  const { flow, viewer } = await implementation;
  const histories = [complete];
  for (let at = 0; at < guards.length; ++at) for (const answer of ['no', 'unknown'])
    histories.push([...prefix, ...Array(at).fill('yes'), answer]);
  const drawings = new Map();
  for (const choices of histories) {
    let state = replay(flow, choices);
    assert.deepEqual(flow.evaluateState(state).current, walk(flow, choices).current);
    for (let limit = weight(state) + 1; ; --limit) {
      assert(limit > 0); assert.equal(flow.getFlowDomainId(state), domain);
      assert.deepEqual(flow.sanitizeState(state), state);
      const value = flow.evaluateState(state);
      if (!drawings.has(state.graph)) drawings.set(state.graph, checkSvg(flow, value.graph));
      const svg = drawings.get(state.graph);
      assert(svg.includes(`data-node="${value.current.id}"`));
      for (const node of value.path) assert(svg.includes(`data-node="${node.id}"`));
      for (const edge of value.edges) assert(svg.includes(`data-edge="${edge.from}:${edge.answer}:${edge.to}"`));
      const hash = flow.serializeFlowHash(state);
      assert.deepEqual(flow.parseFlowHash(hash), state); assert.deepEqual(viewer.diagramState(state.graph, hash), state);
      const url = new URL(viewer.diagramViewerUrl(state.graph, '/flowchartcp/', state), 'https://flowchartcp.test');
      assert.equal(url.pathname, `/flowchartcp/diagrams/${state.graph}/`); assert.equal(url.hash, hash);
      assert.deepEqual(viewer.diagramState(state.graph, url.hash), state);
      if (!weight(state)) break;
      const previous = flow.backFlowState(state); assert(weight(previous) < weight(state)); state = previous;
    }
    assert.deepEqual(state, flow.initialState(domain)); assert.deepEqual(flow.backFlowState(state), state);
  }
});

test('strings metadata, article, reference, observable features and canonical walk agree', async () => {
  const { flow } = await implementation;
  const [allMetadata, allReferences, groupMetadata, groupReferences, features, walks] = await Promise.all([
    collection(/^techniques-.*\.json$/), collection(/^references-.*\.json$/),
    json('data/techniques-specific-strings.json'), json('data/references-specific-strings.json'),
    json('data/word-boundary-comma-problem-features.json'), json('data/problem-walks.json'),
  ]);
  const registered = allMetadata.filter(row => row.id === id); assert.equal(registered.length, 1);
  const meta = registered[0]; assert(groupMetadata.some(row => row.id === id));
  assert.equal(meta.kind, 'technique'); assert.equal(meta.status, 'reviewed');
  assert(meta.sources.includes(statement)); assert(meta.sources.includes(sketch));
  const article = await readFile(path.join(site, 'src/content/docs/techniques', id + '.mdx'), 'utf8');
  assert(new RegExp(`^techniqueId: ["']?${id}["']?\\s*$`, 'm').test(article));
  assert.deepEqual([...article.matchAll(/^## (.+)$/gm)].map(match => match[1]),
    ['使う場面', '考え方', '適用条件', 'なぜ正しいか', '計算量', '実装', '関連する手法', '参考資料']);
  assert.equal((article.match(/^```cpp\s*$/gm) ?? []).length, 1);
  assert(!/<(?:details|summary)\b/i.test(article)); assert(article.includes(`techniqueId="${id}"`));
  for (const source of meta.sources) assert(article.includes(source));
  for (const term of [/close_word_boundary_commas/, /std::map/, /std::string_view/, /std::invalid_argument/, /最小の不動点/, /文頭/, /文末/, /100万/, /非公式分析/]) assert.match(article, term);
  assert.doesNotMatch(article, /checker|ASan|UBSan|調査取得|検証件数/);
  const refs = allReferences.filter(row => matching(row) && row.techniqueId === id); assert.equal(refs.length, 1);
  assert(groupReferences.some(row => matching(row) && row.techniqueId === id));
  const ref = refs[0]; assert.equal(ref.url, statement); assert.equal(ref.editorialUrl, sketch);
  assert.equal(ref.verification, 'independent-analysis'); assert.equal(ref.difficulty, null);
  assert.equal(ref.sourceDate, '2018-04-19'); assert.match(ref.verificationNotes, /unofficial|非公式/);
  assert(ref.evidence.trim()); assert.doesNotMatch(ref.evidence, /checker|ASan|UBSan|コンパイル/);
  const originals = features.filter(matching); assert.equal(originals.length, 1); const feature = originals[0];
  assert.deepEqual(feature.techniqueIds, [id]); assert.equal(feature.url, statement); assert.equal(feature.evidenceUrl, sketch);
  assert.equal(feature.reviewStatus, 'verified'); assert.equal(feature.verification, 'independent-analysis');
  assert.equal(feature.publicationDate, '2018-04-19'); assert.equal(feature.exactDateVerified, true);
  assert.equal(feature.difficulty, null); assert.equal(feature.cutoff, '2026-10-14');
  assert.equal(feature.publicationDateStatus, 'contest-before-cutoff');
  const examples = walks.filter(row => matching(row) && row.expectedTechniqueIds.includes(id)); assert.equal(examples.length, 1);
  const example = examples[0]; assert.equal(example.entryGraphId, domain); assert.deepEqual(example.choices, complete);
  assert.equal(example.statementUrl, statement); assert.equal(example.reviewStatus, 'verified');
  assert.equal(example.verificationKind, 'independent-analysis'); assert.deepEqual(example.features, feature.features);
  assert.deepEqual(walk(flow, complete).steps.map(({ graph, node, answer }) => ({ graph, node, answer })), example.steps);
});

test('the original audit is preserved exactly and its later resolution has correct provenance', async () => {
  const [audit, plan] = await Promise.all([json('data/corpus-audits/icpc-2018-world-finals.json'), json('data/coverage-plan.json')]);
  const original = audit.records.find(matching); assert(original);
  const initial = Object.fromEntries(frozen.auditKeys.map(key => [key, original[key]]));
  assert.equal(digest(initial), hashes.auditRecord, 'every original audit field remains unchanged');
  assert.equal(original.classification, 'missing-technique'); assert.deepEqual(original.expectedTechniqueIds, []);
  assert.equal(original.contest.date, '2018-04-19'); assert.equal(original.contest.exactDateVerified, true);
  assert.equal(original.difficulty, null); assert.notEqual(original.technicalFindings.verification, 'official-editorial');
  assert.equal(original.materialStatus.officialEditorialVerified, false);
  assert.equal(original.resolution.status, 'verified'); assert.deepEqual(original.resolution.techniqueIds, [id]);
  assert(original.resolution.notes.trim()); assert.equal(isCorpusSolutionReviewed(original), true);
  const gap = plan.knownGaps.find(row => row.id === id); assert(gap);
  assert.equal(gap.state, 'resolved'); assert.deepEqual(gap.techniqueIds, [id]);
});

test('all frozen 503 walk records retain every step and exact terminal result', async () => {
  const { flow } = await implementation;
  const [walks, graphs] = await Promise.all([json('data/problem-walks.json'), json('data/flows.json')]);
  const previous = walks.slice(0, 503); assert.equal(previous.length, 503);
  assert.equal(digest(previous), hashes.records);
  const raw = previous.map(row => rawWalk(graphs, row));
  assert.equal(digest(raw), hashes.outcomes); assert.equal(digest(raw.map(row => row.steps)), hashes.steps);
  previous.forEach((record, index) => {
    const value = walk(flow, record.choices, record.entryGraphId);
    assert.deepEqual({ graph: value.graph.id, node: value.current.id, type: value.current.type,
      techniques: techniques(value), steps: value.steps }, raw[index]);
    assert.deepEqual(value.steps.map(({ graph, node, answer }) => ({ graph, node, answer })), record.steps);
    for (const technique of record.expectedTechniqueIds) assert(techniques(value).includes(technique));
  });
});

test('all 449 original graphs retain every old node, terminal, question and answer label', async () => {
  const graphs = await json('data/flows.json'), byId = new Map(graphs.map(graph => [graph.id, graph]));
  assert.equal(frozen.graphs.length, 449);
  const graphHeaders = frozen.graphs.map(id => {
    const graph = byId.get(id); assert(graph); return [id, graph.root, graph.title, graph.entry ?? false];
  });
  assert.equal(digest(graphHeaders), hashes.graphHeaders);
  assert.equal(digest(projectNodes(graphs, frozen.nodes)), hashes.nodes, 'all original node fields, old answers and old option labels remain');
  const terminals = frozen.terminals.map(([id, nodeId]) => {
    const node = byId.get(id)?.nodes.find(node => node.id === nodeId); assert(node);
    return [id, nodeId, node.type, node.techniques ?? [], node.title, node.conditions ?? []];
  });
  assert.equal(digest(terminals), hashes.terminals);
});
